out = {i: dict(zip(["phrases","nouns","question","answer"], [list(R[i][0]), list(R[i][1]), R[i][2], R[i][3]])) for i in src}
json.dump(out, open(f'{H}/cz.json','w'), ensure_ascii=False, indent=1)
